def ext(url, text):
    return f'<a href="{e(url, quote=True)}">{e(text)}</a>'


def local(url, text):
    return f'<a href="{url}">{text}</a>'


def page(title, body, path='/', description='Phoenix voting records, Treasury payments and contract permissions.'):
    nav = ''.join(f'<a href="{u}"' + (' aria-current="page"' if u == path else '') + f'>{t}</a>' for u, t in NAV)
    out = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Phoenix Governance Review</title><meta name="description" content="{e(description)}"><meta name="referrer" content="no-referrer"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{SITE + path}"><meta name="theme-color" content="#173d32"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css?v=20261027-vote-refresh"><script defer src="/site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/">{MARK}<span>Phoenix governance review<small>Votes, payments and contract control</small></span></a><nav class="nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-inner"><div><p>Native tally and scenario: 27 October 2026, 15:07 UTC. Historical vAMP balances: 26 October. Supplemental transaction and funding checks: 27 October. Live state can change.</p></div><nav aria-label="Footer"><a href="/evidence/">Method &amp; sources</a><a href="/record/">Preserved record</a><a href="/privacy/">Privacy</a></nav></div></footer></body></html>'''
    file = DIST / ('index.html' if path == '/' else path.strip('/') + '/index.html')
    file.parent.mkdir(parents=True, exist_ok=True)
    file.write_text(out)


def head(title, desc):
    return f'<div class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Governance review</a></p><h1>{title}</h1><p>{desc}</p></div></div>'


def nextlinks(left, right):
    return f'<nav class="next-reading" aria-label="Continue reading">{local(*left)}{local(*right)}</nav>'


def details(title, body, ident=''):
    idattr = f' id="{ident}"' if ident else ''
    return f'<details class="evidence-detail"{idattr}><summary>{title}</summary><div>{body}</div></details>'


def table(headers, rows, caption=''):
    cap = f'<caption>{caption}</caption>' if caption else ''
    th = ''.join(f'<th scope="col">{h}</th>' for h in headers)
    tr = ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in row) + '</tr>' for row in rows)
    label = re.sub('<[^>]+>', '', caption or ' / '.join(headers))
    return f'<p class="table-scroll-hint">Scroll sideways to read all columns.</p><div class="table-scroll" tabindex="0" role="region" aria-label="{e(label, quote=True)}"><table>{cap}<thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'


def source_list(items):
    return '<ul class="source-list">' + ''.join(f'<li>{ext(u, t)}</li>' for u, t in items) + '</ul>'


# Preserve the retrieved source corpus, but never restore its original narrative over the new review.
for p in (DIST / 'record').rglob('*.html'):
    if 'audit' in p.relative_to(DIST / 'record').parts:
        continue
    backup = ROOT / 'source-records' / 'original-pages' / p.relative_to(DIST / 'record')
    if not backup.exists():
        backup.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, backup)
    s = backup.read_text()
    def relocate(m):
        attr, q, value = m.groups()
        if value.startswith('/') and not value.startswith('//'):
            value = '/record' + value
        elif value.startswith(ORIGINAL):
            value = '/record/' + value[len(ORIGINAL):]
        return attr + '=' + q + value + q
    s = re.sub(r'(href|src|action)=([\'\"])(.*?)\2', relocate, s)
    banner = '<div style="padding:12px 20px;background:#e9f1ed;color:#203e35;font:16px/1.4 sans-serif;text-align:center">Preserved source presentation · <a href="/" style="color:#203e35">Return to the governance review</a></div>'
    p.write_text(re.sub(r'(<body[^>]*>)', r'\1' + banner, s, count=1))

