def number(value, places=0):
    return f'{Decimal(str(value)):,.{places}f}'


def luna_count(count, places=3):
    return number(Decimal(count) / Decimal(1000000), places)


def millions(count):
    return number(Decimal(count) / Decimal(1000000000000), 3) + 'M'


def fresh_validator_rows():
    rows = []
    labels = {'VOTE_OPTION_YES': 'YES', 'VOTE_OPTION_NO': 'NO', 'VOTE_OPTION_NO_WITH_VETO': 'VETO', 'VOTE_OPTION_ABSTAIN': 'ABSTAIN'}
    for row in refresh['validators']:
        if Decimal(row['delegation_uluna']) == 0: continue
        ballot = ' / '.join(labels[o['option']] for o in row['ballot']) or 'No ballot'
        effect = 'No option change' if ballot == 'YES' else ('Enters as YES' if not row['ballot'] else ballot + ' → YES')
        rows.append([e(row['validator']), ballot, millions(row['delegation_uluna']), effect])
    return rows


def insert_before_reading(body, addition):
    position = body.rfind('<nav class="next-reading"')
    assert position >= 0
    return body[:position] + addition + body[position:]

# Homepage: orient a holder before asking them to inspect the records.
home = f'''<section class="hero-review"><div class="wrap hero-review-grid"><div><h1>Before voting on 4853</h1><p class="hero-lead">Proposal 4853 would appoint a temporary supervisor to investigate the Phoenix Foundation’s board dispute and seek powers that could lead to a director’s removal.</p><p>The four concerns below cover who approved payments, which contract powers transferred, whether funded work was accepted, and a failed proposal to reduce the votes needed for board approval.</p><div class="action-row"><a class="button" href="#findings">Read the four concerns {ARROW}</a><a class="button secondary" href="/voting/#if-passes">What passing 4853 changes</a></div><p class="hero-caveat">This review does not recommend YES, NO or anyone’s removal.</p></div><aside class="vote-deadline" aria-label="Proposal 4853 snapshot"><p class="status-live">27 October 2026 · 15:07 UTC</p><h2>Voting closes 31 October.</h2><dl><div><dt>YES, excluding abstain</dt><dd>{number(base_metrics['yes_share_non_abstain_percent'], 2)}%</dd></div><div><dt>VETO, all votes</dt><dd>{number(base_metrics['veto_share_all_percent'], 2)}%</dd></div><div><dt>Recorded ballots</dt><dd>{refresh['ballot_count']}</dd></div></dl><p>Closes at <strong>03:40 UTC</strong>. This is a dated snapshot; the tally can change.</p><a href="/voting/#scenario">What if the ampLUNA hub voted YES?</a></aside></div></section>
<div class="wrap"><section class="section" id="findings"><div class="section-heading"><h2>Four concerns in the records</h2></div><div class="finding-list"><article class="finding"><h3>0xphilipp helped approve releases from ERIS’s Creda grant</h3><p>0xphilipp proposed and voted YES on A209, enabling <strong>200,000 USDC</strong> for Creda’s first three milestones. Vini and MB supplied the other two YES votes. A215 later enabled another <strong>10,000 USDC</strong> for analytics, bringing the grant total to <strong>210,000 USDC</strong>.</p><p class="note">Both were three-director approvals. The Treasury action marks all four milestones claimed. These amounts funded the project; they do not establish personal profit or independent acceptance of the work.</p><a href="/stakeholders/#creda-approval">Creda’s grant, approval votes and milestones</a></article>
<article class="finding"><h3>The handover left some contract powers unchanged</h3><p>ERIS proposal 9 gave the Phoenix board upgrade control over two contracts. The hub’s internal owner and the ICS20 contract’s internal governance setting did not change. Other Treasury and TLA permissions also remain.</p><p class="note">A contract’s upgrade administrator and its internal owner can have different powers. The records identify authorized addresses; they do not establish who holds every key.</p><a href="/governance/#handover">Which powers transferred and which remain</a></article>
<article class="finding"><h3>Payment records do not show acceptance of every milestone</h3><p>Phoenix grants identified for Creda, Votion and the migration app total 265,000 USDC. Transfers and claimed milestones are recorded; independent acceptance of every deliverable has not been established.</p><p class="note">AADAO separately reports Votion’s Hydro work complete and jointly verified. Project funding is not personal profit, and a later unfinished page does not prove that no work occurred.</p><a href="/treasury/#project-funding">Funding, delivered work and missing acceptance records</a></article>
<article class="finding"><h3>A272 proposed concentrating board approval power</h3><p>A272 proposed removing Vini and lowering the approval threshold to 60%, allowing two of the remaining three seats to approve an action. It failed: 0xphilipp and MB voted YES, Rose voted NO and Vini was absent.</p><p class="note">The board remained four seats with a 75% threshold. 4853 now seeks a supervisor and removal-facilitation powers over the same dispute. A later removal and threshold change could reopen the concentration risk; neither happens automatically on passage.</p><a href="/voting/#removal-risk">The route from failed A272 to proposal 4853</a></article></div></section>
<section class="section section-grid" id="voting-power"><div class="section-intro"><h2>Could the hub change the vote?</h2></div><div><p>In the 27 October snapshot, a full YES vote from the ampLUNA hub would raise YES from <strong>{number(base_metrics['yes_share_non_abstain_percent'], 2)}%</strong> to <strong>{number(scenario_metrics['yes_share_non_abstain_percent'], 2)}%</strong> of non-abstain votes, changing the result from failing to passing if nothing else changed.</p><p>The hub had not voted, and its vAMP gauge had no recorded votes. Validators voted differently: Smart Stake and Ceres chose VETO; HighStakes chose ABSTAIN. The calculation shows potential voting power, not a voting agreement.</p><a href="/voting/#scenario">See the assumptions and validator breakdown {ARROW}</a></div></section>
<section class="section" id="immediate"><div class="section-heading"><h2>Before the vote closes</h2></div><ol class="action-list"><li><div><h3>Disclose financial interests</h3><p>Directors, Think Tank members, validators and contractors should disclose relevant payments, grants, hosting arrangements and voting interests under their public role or handle.</p></div><a href="/stakeholders/">Who has which role</a></li><li><div><h3>Publish voting instructions</h3><p>Explain planned hub and gauge votes. Where a validator follows a DAO mandate, finish the internal vote first. Lion DAO’s validator changed to YES while its A33 vote was still open.</p></div><a href="/voting/#lion-dao">Lion DAO’s voting sequence</a></li><li><div><h3>Provide the missing approval records</h3><p>Publish recusal decisions, milestone acceptance, contract handover terms and any approved extensions. Retain the ballots, payment records and responses for independent review.</p></div><a href="/governance/#reforms">Proposed governance changes</a></li></ol></section>
<section class="section reading"><h2>Check the sources</h2><p>The source library includes ballot exports, transaction responses and calculation files. The 27 October supplement checked 48 successful transactions, including 38 Terra transaction-byte hashes. Six cited transactions remain unavailable. This is not an independent audit of every transaction.</p><a href="/evidence/">Sources, verification method and limits {ARROW}</a></section></div>'''
